// validatorCase is one row of Django's TEST_DATA: a validator, a value and
// whether the validator accepts it.
type validatorCase struct {
	name      string
	validator forms.Validator
	value     any
	valid     bool
}

// passes returns a row where validator accepts value.
func passes(name string, validator forms.Validator, value any) validatorCase {
	return validatorCase{name: name, validator: validator, value: value, valid: true}
}

// fails returns a row where validator rejects value with a ValidationError.
func fails(name string, validator forms.Validator, value any) validatorCase {
	return validatorCase{name: name, validator: validator, value: value}
}

// asValidator converts a plain validator function to forms.Validator.
func asValidator(f func(any) error) forms.Validator { return f }

// mustRegexp compiles pattern; Python re flags are given as Go inline flags,
// for example "(?i)".
func mustRegexp(pattern string) *regexp.Regexp { return regexp.MustCompile(pattern) }

