// Ported from Django: tests/validators/tests.py::TestValidators.test_validators
func TestValidators(t *testing.T) {
	for _, c := range validatorTestData() {
		name := fmt.Sprintf("%s/%q", c.name, fmt.Sprint(c.value))
		t.Run(name, func(t *testing.T) {
			err := c.validator(c.value)
			if c.valid {
				if err != nil {
					t.Errorf("%s(%#v) = %v, want nil", c.name, c.value, err)
				}
				return
			}
			var ve *forms.ValidationError
			if !errors.As(err, &ve) {
				t.Errorf("%s(%#v) = %v, want a *ValidationError", c.name, c.value, err)
			}
		})
	}
}

// emailError validates value with EmailValidator and returns the
// ValidationError, failing the test when the value passes.
func emailError(t *testing.T, value string) *forms.ValidationError {
	t.Helper()
	err := forms.EmailValidator()(value)
	var ve *forms.ValidationError
	if !errors.As(err, &ve) {
		t.Fatalf("EmailValidator()(%q) = %v, want a *ValidationError", value, err)
	}
	return ve
}

// Ported from Django: tests/validators/tests.py::EmailValidatorTests.test_invalid_domain_error
func TestEmailValidatorInvalidDomainError(t *testing.T) {
	ve := emailError(t, "local@invalid_domain")
	equal(t, ve.Code, "invalid")
	equal(t, ve.Params, map[string]any{"value": "local@invalid_domain", "domain": "invalid_domain"})
}

// Ported from Django: tests/validators/tests.py::EmailValidatorTests.test_invalid_username_error
func TestEmailValidatorInvalidUsernameError(t *testing.T) {
	ve := emailError(t, "not valid@example.com")
	equal(t, ve.Code, "invalid")
	equal(t, ve.Params, map[string]any{"value": "not valid@example.com", "username": "not valid"})
}

